mapper.select:
SELECT COUNT(id)
FROM review_likes
WHERE review_id = #{reviewId}

SELECT COUNT(*)
FROM review_likes
WHERE review_id = #{reviewId} AND user_id = #{userId}

SELECT companion
FROM review
WHERE user_id = #{userId}

SELECT r.id, r.title, r.location, u.gender, u.birthday, i.img_url AS imgUrl, GROUP_CONCAT(DISTINCT h.hashtag) AS hashtags FROM review r JOIN user u ON r.user_id = u.id LEFT JOIN hashtag h ON r.id = h.review_id LEFT JOIN image i ON r.id = i.owner_id AND i.type = 'review' AND i.rep_img_yn = 'Y' WHERE r.user_id != #{userId} AND u.gender = #{gender}
AND (
r.companion IN
#{c}
OR
h.hashtag IN
#{h}
)
GROUP BY r.id, r.title, r.location, u.gender, u.birthday, i.img_url ORDER BY r.id DESC
